<#
    APPLY_ICONFESS_PLATFORM.ps1

    Applies the backend platform work to a local clone of
    https://github.com/Teamthy/i-confess.git and prepares the commit.

    What it does
      1. Verifies you are in the right repo on the expected base commit.
      2. Writes every changed/new file (embedded, gzip+base64 - no network).
      3. Untracks the 15.7 MB committed binary and the .history/ editor
         backups, which bloat every clone.
      4. Runs gofmt / go vet / go test so you never push a red build.
      5. Prints `git status` and the exact commit+push commands.

    It does NOT commit or push for you. Review the diff first.

    Usage
      powershell -NoProfile -ExecutionPolicy Bypass -File .\APPLY_ICONFESS_PLATFORM.ps1
      ...add -SkipTests to write files without running the Go test suite.
#>

[CmdletBinding()]
param(
    [switch]$SkipTests,
    [switch]$Force
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

function Say([string]$m){ Write-Host "==> $m" -ForegroundColor Cyan }
function Ok ([string]$m){ Write-Host "    $m" -ForegroundColor Green }
function Warn([string]$m){ Write-Host "    $m" -ForegroundColor Yellow }
function Die([string]$m){ Write-Host "ERROR: $m" -ForegroundColor Red; exit 1 }

Say "i-confess backend platform - full-file write"

# ---------------------------------------------------------------- repo checks
$RepoRoot = (Get-Location).Path
if (-not (Test-Path (Join-Path $RepoRoot '.git'))) {
    Die "Not a git repository: $RepoRoot`n       cd into your i-confess clone and re-run."
}
if (-not (Test-Path (Join-Path $RepoRoot 'server\go.mod'))) {
    Die "server\go.mod not found. This does not look like the i-confess repo."
}
Say "Repo root: $RepoRoot"

$expectedBase = '1d59b66'
$head = (git rev-parse --short HEAD).Trim()
if ($head -ne $expectedBase) {
    Warn "HEAD is $head; these changes were built against $expectedBase."
    if (-not $Force) {
        $ans = Read-Host "    Continue anyway? (y/N)"
        if ($ans -ne 'y') { Die "Aborted. Use -Force to skip this prompt." }
    }
}

$dirty = git status --porcelain
if ($dirty -and -not $Force) {
    Warn "Working tree is not clean. Existing changes may be overwritten."
    $ans = Read-Host "    Continue? (y/N)"
    if ($ans -ne 'y') { Die "Aborted. Commit or stash first, or pass -Force." }
}

# ------------------------------------------------------------- write payload
Add-Type -AssemblyName System.IO.Compression | Out-Null

function Write-Payload {
    param([string]$RelPath, [string]$B64)

    $full = Join-Path $RepoRoot $RelPath
    $dir  = Split-Path -Parent $full
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }

    $gz  = [Convert]::FromBase64String($B64)
    $in  = New-Object System.IO.MemoryStream(,$gz)
    $ds  = New-Object System.IO.Compression.GzipStream($in, [System.IO.Compression.CompressionMode]::Decompress)
    $out = New-Object System.IO.MemoryStream
    $ds.CopyTo($out); $ds.Dispose(); $in.Dispose()
    $bytes = $out.ToArray(); $out.Dispose()

    # Write raw bytes: no encoding transform, no BOM, LF endings preserved.
    [System.IO.File]::WriteAllBytes($full, $bytes)
    "{0,9:N0}  {1}" -f $bytes.Length, $RelPath | Write-Host
    return $bytes.Length
}

