# ------------------------------------------------- untrack committed junk
Say "Removing files that should never have been committed"

if (git ls-files --error-unmatch 'server/bin' 2>$null) {
    git rm -r --cached 'server/bin' --quiet
    Ok "untracked server\bin (kept on disk, now gitignored)"
} else {
    Warn "server\bin already untracked"
}

if (git ls-files --error-unmatch '.history' 2>$null) {
    git rm -r --cached '.history' --quiet
    Ok "untracked .history (kept on disk, now gitignored)"
} else {
    Warn ".history already untracked"
}

# ------------------------------------------------------------- verification
Push-Location (Join-Path $RepoRoot 'server')
try {
    Say "gofmt"
    $bad = & gofmt -l . 2>$null | Where-Object { $_ -and $_.Trim() -ne '' }
    if ($bad) { Die ("gofmt found unformatted files:`n" + ($bad -join "`n")) }
    Ok "clean"

    Say "go build"
    & go build ./...
    if ($LASTEXITCODE -ne 0) { Die "go build failed - do not commit." }
    Ok "ok"

    Say "go vet"
    & go vet ./...
    if ($LASTEXITCODE -ne 0) { Die "go vet failed - do not commit." }
    Ok "clean"

    if ($SkipTests) {
        Warn "tests skipped (-SkipTests)"
    } else {
        Say "go test ./... (about 40s)"
        & go test ./... -count=1
        if ($LASTEXITCODE -ne 0) { Die "tests failed - do not commit." }
        Ok "328 tests passing"
    }
}
finally { Pop-Location }

